  @override
  String get termsBody =>
      'VH Health-ലേക്ക് സ്വാഗതം. ഈ മൊബൈൽ ആപ്ലിക്കേഷൻ ഉപയോഗിക്കുന്നതിലൂടെ, നിങ്ങൾ ഈ ഉപയോഗ നിബന്ധനകൾ അംഗീകരിക്കുന്നു.\n\n1. ലക്ഷ്യം: VH Health എന്നത് രോഗികൾക്ക് അവരുടെ ആരോഗ്യ രേഖകൾ, അപ്പോയിന്റ്മെന്റുകൾ, കുറിപ്പടികൾ, അന്വേഷണങ്ങൾ, ആശുപത്രിയുമായുള്ള ആശയവിനിമയം എന്നിവ നിയന്ത്രിക്കാൻ സഹായിക്കുന്ന ഒരു മൊബൈൽ ആപ്ലിക്കേഷനാണ്.\n2. യോഗ്യത: ഈ ആപ്പ് സ്വതന്ത്രമായി ഉപയോഗിക്കുന്നതിന് നിങ്ങൾക്ക് കുറഞ്ഞത് 18 വയസ്സ് പ്രായമുണ്ടായിരിക്കണം. പ്രായപൂർത്തിയാകാത്തവരുടെ ഉപയോഗം ഒരു രക്ഷിതാവിന്റെ മേൽനോട്ടത്തിലായിരിക്കണം.\n3. സേവനങ്ങളുടെ ഉപയോഗം:\n   • നിങ്ങൾ കൃത്യവും പൂർണ്ണവുമായ വിവരങ്ങൾ നൽകുമെന്ന് സമ്മതിക്കുന്നു.\n   • ആപ്പിന്റെ പ്രവർത്തനത്തെ ദുരുപയോഗം ചെയ്യുകയോ തടസ്സപ്പെടുത്തുകയോ ചെയ്യില്ലെന്ന് നിങ്ങൾ സമ്മതിക്കുന്നു.\n   • നിയമവിരുദ്ധമോ നിരോധിതമോ ആയ ഏതൊരു ഉപയോഗവും കർശനമായി വിലക്കിയിരിക്കുന്നു.\n4. ബൗദ്ധിക സ്വത്ത്: ലോഗോകൾ, ടെക്സ്റ്റ്, ചിത്രങ്ങൾ, ഡാറ്റ എന്നിവയുൾപ്പെടെ ആപ്പിലെ എല്ലാ ഉള്ളടക്കവും VH Health-ന്റെയോ അതിന്റെ ലൈസൻസർമാരുടെയോ സ്വത്താണ്, അവ ബാധകമായ പകർപ്പവകാശ, വ്യാപാരമുദ്ര നിയമങ്ങളാൽ സംരക്ഷിക്കപ്പെട്ടിരിക്കുന്നു.\n5. മാറ്റങ്ങൾ: ഏത് സമയത്തും, അറിയിപ്പോടുകൂടിയോ അല്ലാതെയോ, ഏതെങ്കിലും ഫീച്ചറോ പ്രവർത്തനമോ പരിഷ്കരിക്കാനോ നിർത്തലാക്കാനോ ഞങ്ങൾക്ക് അവകാശമുണ്ട്.\n6. അവസാനിപ്പിക്കൽ: നിബന്ധനകൾ ലംഘിക്കുകയോ ദുരുപയോഗം ചെയ്യുകയോ ചെയ്യുന്ന ഏതൊരു ഉപയോക്താവിന്റെയും ആക്സസ് VH Health-ന് താൽക്കാലികമായി നിർത്തുകയോ അവസാനിപ്പിക്കുകയോ ചെയ്യാം.';

  @override
  String get conditionsBody =>
      '1. **മെഡിക്കൽ ഉപദേശ നിരാകരണം:**\n   • ഈ ആപ്പ് പൊതുവായ വിവരങ്ങൾക്കും സൗകര്യത്തിനും വേണ്ടിയുള്ളതാണ്.\n   • ഇത് യോഗ്യതയുള്ള ആരോഗ്യ വിദഗ്ദ്ധരുമായുള്ള നേരിട്ടുള്ള കൺസൾട്ടേഷന് പകരമാവില്ല.\n   • രോഗനിർണയത്തിനും ചികിത്സയ്ക്കും എല്ലായ്പ്പോഴും നിങ്ങളുടെ ഡോക്ടറെയോ ആശുപത്രി ജീവനക്കാരെയോ സമീപിക്കുക.\n\n2. അടിയന്തര ഉപയോഗം:\n   • ഈ ആപ്പ് അടിയന്തര വൈദ്യസഹായത്തിനായി ഉദ്ദേശിച്ചുള്ളതല്ല.\n   • അടിയന്തര സാഹചര്യങ്ങളിൽ, ദയവായി നിങ്ങളുടെ പ്രാദേശിക എമർജൻസി നമ്പറിൽ വിളിക്കുകയോ അടുത്തുള്ള ആശുപത്രിയിൽ പോകുകയോ ചെയ്യുക.\n\n3. സേവന ലഭ്യത:\n   • ഞങ്ങൾ സ്ഥിരമായ ലഭ്യതയ്ക്കായി പരിശ്രമിക്കുന്നു, പക്ഷേ തടസ്സമില്ലാത്ത ആക്സസ് ഉറപ്പുനൽകുന്നില്ല.\n   • സാങ്കേതിക പ്രശ്നങ്ങൾ, അപ്‌ഡേറ്റുകൾ, അല്ലെങ്കിൽ നെറ്റ്‌വർക്ക് തകരാറുകൾ എന്നിവ ഇടയ്ക്കിടെ ആക്സസ്സിനെ ബാധിച്ചേക്കാം.\n\n4. ഡാറ്റയുടെ കൃത്യത:\n   • അപ്പോയിന്റ്മെന്റ് ഷെഡ്യൂളുകളും റിപ്പോർട്ടുകളും പോലുള്ള വിവരങ്ങൾ ആശുപത്രി സിസ്റ്റങ്ങളിൽ നിന്ന് വീണ്ടെടുക്കുന്നതിനാൽ അവ മാനുവൽ എൻട്രിക്ക് വിധേയമായിരിക്കാം.\n   • തെറ്റായ ഡാറ്റാ എൻട്രി അല്ലെങ്കിൽ മൂന്നാം കക്ഷി സിസ്റ്റം പ്രശ്നങ്ങൾ മൂലമുണ്ടാകുന്ന പിശകുകൾക്ക് VH Health ഉത്തരവാദിയല്ല.';

  @override
  String get privacyBody =>
      '1. **വിവര ശേഖരണം:**\n   • നിങ്ങളുടെ പേര്, ഫോൺ നമ്പർ, UID, മെഡിക്കൽ റെക്കോർഡുകൾ, അപ്പോയിന്റ്മെന്റ് ഡാറ്റ, അപ്‌ലോഡുകൾ എന്നിവ ഞങ്ങൾ ശേഖരിക്കുന്നു.\n   • ആപ്പിന്റെ പ്രകടനം മെച്ചപ്പെടുത്തുന്നതിനായി ഞങ്ങൾ ഉപകരണ ഐഡന്റിഫയറുകളും ഉപയോഗ വിശകലനങ്ങളും ശേഖരിച്ചേക്കാം.\n\n2. വിവരങ്ങളുടെ ഉപയോഗം:\n   • നിങ്ങളുടെ വിവരങ്ങൾ ആപ്പിനുള്ളിൽ സേവനങ്ങൾ നൽകുന്നതിന് മാത്രമായി ഉപയോഗിക്കുന്നു.\n   • ഞങ്ങൾ നിങ്ങളുടെ ഡാറ്റ വിൽക്കുകയോ പരസ്യ ആവശ്യങ്ങൾക്കായി ഉപയോഗിക്കുകയോ ചെയ്യുന്നില്ല.\n\n3. ഡാറ്റ പങ്കുവെക്കൽ:\n   • നിങ്ങളുടെ പരിചരണത്തിൽ ഏർപ്പെട്ടിരിക്കുന്ന അംഗീകൃത ആശുപത്രി ജീവനക്കാരുമായും മെഡിക്കൽ പ്രൊഫഷണലുകളുമായും നിങ്ങളുടെ ഡാറ്റ പങ്കിട്ടേക്കാം.\n   • നിയമപ്രകാരം ആവശ്യപ്പെടുകയാണെങ്കിൽ അല്ലെങ്കിൽ നിയമപരമായ ബാധ്യതകളുടെ കാര്യത്തിൽ ഞങ്ങൾ ഡാറ്റ വെളിപ്പെടുത്തിയേക്കാം.\n\n4. ഡാറ്റ സുരക്ഷ:\n   • നിങ്ങളുടെ ഡാറ്റ പരിരക്ഷിക്കുന്നതിന് ഞങ്ങൾ വ്യവസായ-നിലവാരത്തിലുള്ള സുരക്ഷാ രീതികൾ ഉപയോഗിക്കുന്നു.\n   • എന്നിരുന്നാലും, ഒരു സിസ്റ്റവും 100% സുരക്ഷിതമല്ല; ആപ്പിന്റെ ഉപയോഗം നിങ്ങളുടെ സ്വന്തം ഉത്തരവാദിത്തത്തിലാണ്.\n\n5. നിങ്ങളുടെ അവകാശങ്ങൾ:\n   • നിങ്ങളുടെ സംഭരിച്ച വിവരങ്ങളിലേക്ക് പ്രവേശനം അഭ്യർത്ഥിക്കുകയോ തിരുത്തലുകൾ ആവശ്യപ്പെടുകയോ ചെയ്യാം.\n   • ആശുപത്രി ഭരണകൂടവുമായി ബന്ധപ്പെട്ട് നിങ്ങളുടെ അക്കൗണ്ട് ഇല്ലാതാക്കാൻ നിങ്ങൾക്ക് അഭ്യർത്ഥിക്കാം.\n\n6. ഡാറ്റ നിലനിർത്തൽ:\n   • ആരോഗ്യ സംരക്ഷണത്തിനോ നിയമപരമായ ആവശ്യങ്ങൾക്കോ ആവശ്യമുള്ളിടത്തോളം കാലം നിങ്ങളുടെ ഡാറ്റ നിലനിർത്തും.';

